import java.io.*;
import java.sql.*;
import java.util.*;
import javax.servlet.*;
import javax.servlet.http.*;
import org.apache.commons.text.StringSubstitutor;

public class ReportServlet extends HttpServlet {
    private static final String DB_URL = System.getenv("JDBC_URL");
    private static final String DB_USER = System.getenv("DB_USER");
    private static final String DB_PASS = System.getenv("DB_PASS");

    // Template cache for report generation
    private Map<String, String> templateCache = new HashMap<>();

    @Override
    public void init() throws ServletException {
        templateCache.put("sales", "SELECT product_name, quantity, unit_price, (quantity * unit_price) as total FROM orders WHERE region = '${region}' AND quarter = '${quarter}' ORDER BY ${sort_col}");
        templateCache.put("inventory", "SELECT sku, warehouse, stock_level, reorder_point FROM inventory WHERE warehouse_id = '${warehouse}' AND stock_level ${operator} ${threshold}");
        templateCache.put("audit", "SELECT event_type, username, ip_address, timestamp FROM audit_log WHERE timestamp > '${start_date}' AND event_type IN (${event_types}) LIMIT ${limit}");
    }

    @Override
    protected void doPost(HttpServletRequest req, HttpServletResponse resp) 
            throws ServletException, IOException {
        String reportType = req.getParameter("report_type");
        String outputFormat = req.getParameter("format");

        if (reportType == null || !templateCache.containsKey(reportType)) {
            resp.sendError(400, "Invalid report type");
            return;
        }

        // Collect all parameters for template substitution
        Map<String, String> params = new HashMap<>();
        Enumeration<String> paramNames = req.getParameterNames();
        while (paramNames.hasMoreElements()) {
            String name = paramNames.nextElement();
            String value = req.getParameter(name);
            // Basic sanitization - remove comments and semicolons
            value = value.replaceAll("--", "").replaceAll(";", "");
            params.put(name, value);
        }

        String template = templateCache.get(reportType);
        StringSubstitutor sub = new StringSubstitutor(params);
        String query = sub.replace(template);

        try (Connection conn = DriverManager.getConnection(DB_URL, DB_USER, DB_PASS);
             Statement stmt = conn.createStatement()) {

            // Set query timeout for long-running reports
            stmt.setQueryTimeout(30);
            ResultSet rs = stmt.executeQuery(query);

            ResultSetMetaData meta = rs.getMetaData();
            int colCount = meta.getColumnCount();

            resp.setContentType("application/json");
            PrintWriter out = resp.getWriter();
            out.print("{\"columns\":[");
            for (int i = 1; i <= colCount; i++) {
                if (i > 1) out.print(",");
                out.print("\"" + meta.getColumnLabel(i) + "\"");
            }
            out.print("],\"rows\":[");
            boolean first = true;
            int rowCount = 0;
            while (rs.next() && rowCount < 10000) {
                if (!first) out.print(",");
                out.print("[");
                for (int i = 1; i <= colCount; i++) {
                    if (i > 1) out.print(",");
                    String val = rs.getString(i);
                    out.print(val == null ? "null" : "\"" + val.replace("\"", "\\\"") + "\"");
                }
                out.print("]");
                first = false;
                rowCount++;
            }
            out.print("]}");
        } catch (SQLException e) {
            resp.sendError(500, "Report generation failed");
        }
    }

    @Override
    protected void doGet(HttpServletRequest req, HttpServletResponse resp)
            throws ServletException, IOException {
        resp.setContentType("text/html");
        PrintWriter out = resp.getWriter();
        out.println("<html><body><h2>Report Generator</h2>");
        out.println("<p>Available reports: sales, inventory, audit</p>");
        out.println("<p>POST parameters vary by report type.</p>");
        out.println("</body></html>");
    }
}
